import{_ as c,C as l,o,c as p,a2 as r,b as n,w as t,a,E as s,a3 as d}from"./chunks/framework.CZqXuAiL.js";const b=JSON.parse(`{"title":"Architecture Overview","description":"Inside NitroCord's protection engine — the Netty pipeline, the connection lifecycle gates, the violation system, the kernel firewall, the threading model, file layout, and performance design.","frontmatter":{"title":"Architecture Overview","description":"Inside NitroCord's protection engine — the Netty pipeline, the connection lifecycle gates, the violation system, the kernel firewall, the threading model, file layout, and performance design."},"headers":[],"relativePath":"nitrocord/architecture/overview.md","filePath":"nitrocord/architecture/overview.md","lastUpdated":1785341162000}`),h={name:"nitrocord/architecture/overview.md"};function m(u,e,f,g,y,k){const i=l("Mermaid");return o(),p("div",null,[e[4]||(e[4]=r('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><blockquote><p><strong>A stock Velocity pipeline, plus a full protection engine.</strong> This page walks through how NitroCord is put together: where its handlers sit in the Netty pipeline, which gates a connection passes and in what order, how a single bad packet escalates into a kernel-level firewall ban, and why none of it ever blocks a network thread.</p></blockquote><nav class="table-of-contents"><ul><li><a href="#design-principles">Design principles</a></li><li><a href="#the-netty-pipeline">The Netty pipeline</a></li><li><a href="#connection-lifecycle">Connection lifecycle</a></li><li><a href="#the-violation-system">The violation system</a></li><li><a href="#the-kernel-firewall">The kernel firewall</a></li><li><a href="#component-map">Component map</a></li><li><a href="#threading-model">Threading model</a></li><li><a href="#file-layout">File layout</a></li><li><a href="#performance-notes">Performance notes</a></li><li><a href="#next-steps">Next steps</a></li></ul></nav><hr><h2 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design principles&quot;">​</a></h2><p>NitroCord is a fork of Velocity 4.1.0 held to three golden rules:</p><ul><li><strong>Plugin compatibility is sacred.</strong> No <code>com.velocitypowered.*</code> package, class or public API signature is ever renamed or modified. Plugins compiled against <code>velocity-api</code> keep working unchanged.</li><li><strong>Minimal upstream edits.</strong> Edits to upstream files are limited to one-line hooks delegating into NitroCord code, so merging future Velocity releases stays a mechanical process.</li><li><strong>All protection logic lives in <code>com.nitrocord.*</code>.</strong> Every check, service and handler is NitroCord-owned code, configured through <code>nitrocord.toml</code> and <code>protection.toml</code> — two standalone files that live next to <code>velocity.toml</code>.</li></ul><p>Two practical consequences for admins:</p><ul><li><strong>Configuration is read live.</strong> Checks read the current <code>protection.toml</code> snapshot on every invocation, so <code>/nitrocord reload</code> takes effect immediately — no restart, no gap in protection.</li><li><strong>Everything self-gates on the license.</strong> Without a valid license key (license enforcement happens before bind, and if a background re-check later denies the key) every gate, check and handler passes traffic through untouched, and the proxy behaves like stock Velocity.</li></ul><hr><h2 id="the-netty-pipeline" tabindex="-1">The Netty pipeline <a class="header-anchor" href="#the-netty-pipeline" aria-label="Permalink to &quot;The Netty pipeline&quot;">​</a></h2><p>NitroCord inserts exactly two handlers into every server channel pipeline:</p><table tabindex="0"><thead><tr><th>Pipeline name</th><th>Handler</th><th>Position</th><th>Job</th></tr></thead><tbody><tr><td><code>nitrocord-firewall-gate</code></td><td><code>NitroFirewallGateHandler</code></td><td>First handler (<code>addFirst</code>)</td><td>Accept-time gate: firewall, whitelist fast path, cached anti-VPN verdict, TCP fingerprint</td></tr><tr><td><code>nitrocord-packet-guard</code></td><td><code>NitroPacketGuardHandler</code></td><td>Immediately after <code>frame-decoder</code></td><td>Packet flood scoring — one <code>ByteBuf</code> is exactly one framed serverbound packet</td></tr></tbody></table>',13)),(o(),n(d,null,{default:t(()=>[s(i,{id:"mermaid-105",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20C%5B%22TCP%20connection%20accepted%22%5D%20--%3E%20GATE%5B%22nitrocord-firewall-gate%3Cbr%2F%3Eruns%20on%20channelActive%2C%20before%20any%20decoding%22%5D%0A%20%20%20%20GATE%20--%3E%7C%22firewalled%22%7C%20CLOSE1%5B%22channel%20closed%20immediately%3Cbr%2F%3Ecounted%20as%20blocked%22%5D%0A%20%20%20%20GATE%20--%3E%7C%22cached%20anti-VPN%20hit%20%2F%20bad%20fingerprint%22%7C%20RST%5B%22silent%20TCP%20RST%22%5D%0A%20%20%20%20GATE%20--%3E%7C%22allowed%22%7C%20LPD%5B%22legacy-ping-decoder%22%5D%0A%20%20%20%20LPD%20--%3E%20FD%5B%22frame-decoder%3Cbr%2F%3EMinecraftVarintFrameDecoder%22%5D%0A%20%20%20%20FD%20--%3E%20PG%5B%22nitrocord-packet-guard%3Cbr%2F%3Escores%20every%20framed%20packet%22%5D%0A%20%20%20%20PG%20--%3E%7C%22ALLOW%22%7C%20RT%5B%22read-timeout%22%5D%0A%20%20%20%20RT%20--%3E%20MD%5B%22minecraft-decoder%22%5D%20--%3E%20ME%5B%22minecraft-encoder%22%5D%20--%3E%20H%5B%22handler%3Cbr%2F%3EMinecraftConnection%20%E2%86%92%20session%20handlers%22%5D%0A%20%20%20%20PG%20--%3E%7C%22CANCEL%22%7C%20REL%5B%22buffer%20released%2C%20logged%20(throttled)%3Cbr%2F%3Econnection%20stays%20open%22%5D%0A%20%20%20%20PG%20--%3E%7C%22KICK%22%7C%20REL2%5B%22buffer%20released%2C%20channel%20closed%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=r('<p>Because the firewall gate runs on <code>channelActive</code>, a firewalled source is rejected before any decoding, timeout handling or connection bookkeeping runs — the cheapest possible denial short of the kernel dropping the packet itself.</p><div class="warning custom-block"><p class="custom-block-title">HAProxy caveat</p><p>When <code>proxy-protocol</code> is enabled, Velocity inserts the HAProxy decoder ahead of the gate, and the gate acts before the HAProxy message is decoded — so it sees your load balancer&#39;s address, not the client&#39;s. Firewall and whitelist entries only match direct connections, and <code>tcp-fingerprint</code> inspects the load balancer&#39;s own socket. Disable <code>tcp-fingerprint</code> on HAProxy setups.</p></div><hr><h2 id="connection-lifecycle" tabindex="-1">Connection lifecycle <a class="header-anchor" href="#connection-lifecycle" aria-label="Permalink to &quot;Connection lifecycle&quot;">​</a></h2><p>Every connection walks a fixed sequence of gates. The order is deliberate: the cheapest, most certain checks run first, and anything that costs network I/O runs asynchronously, off the event loop.</p>',5)),(o(),n(d,null,{default:t(()=>[s(i,{id:"mermaid-121",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20ACCEPT%5B%22Accept%20(channelActive%20%E2%80%94%20before%20any%20decoding)%22%5D%0A%20%20%20%20%20%20%20%20A1%5B%22Kernel%20firewall%20gate%22%5D%20--%3E%20A2%7B%22Verified%20whitelist%20address%3F%22%7D%0A%20%20%20%20%20%20%20%20A2%20--%3E%7C%22yes%20%E2%80%94%20fast%20path%22%7C%20PASS%5B%22continue%20into%20the%20Velocity%20pipeline%22%5D%0A%20%20%20%20%20%20%20%20A2%20--%3E%7C%22no%22%7C%20A3%7B%22Cached%20positive%20anti-VPN%20verdict%3F%22%7D%0A%20%20%20%20%20%20%20%20A3%20--%3E%7C%22yes%22%7C%20X1%5B%22silent%20TCP%20RST%22%5D%0A%20%20%20%20%20%20%20%20A3%20--%3E%7C%22no%22%7C%20A4%7B%22TCP%20fingerprint%20clean%3F%3Cbr%2F%3E(attack-mode%20gated)%22%7D%0A%20%20%20%20%20%20%20%20A4%20--%3E%7C%22no%22%7C%20X2%5B%22violation%20strike%20%2B%20silent%20TCP%20RST%22%5D%0A%20%20%20%20%20%20%20%20A4%20--%3E%7C%22yes%20%2F%20unavailable%22%7C%20PASS%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20HANDSHAKE%5B%22Handshake%20(LOGIN%20intent)%22%5D%0A%20%20%20%20%20%20%20%20B1%5B%22Record%20connection%3Cbr%2F%3Eper-IP%20counters%20%2B%20global%20stats%22%5D%20--%3E%20B2%5B%22Anti-hang%20re-arm%3Cbr%2F%3E2s%20read%20timeout%20during%20attack%20mode%22%5D%0A%20%20%20%20%20%20%20%20B2%20--%3E%20B3%7B%22Whitelist%20verified%3F%22%7D%0A%20%20%20%20%20%20%20%20B3%20--%3E%7C%22yes%20%E2%80%94%20skip%20the%20gate's%20checks%22%7C%20B5%0A%20%20%20%20%20%20%20%20B3%20--%3E%7C%22no%22%7C%20B4%5B%22Rate%20limit%20%E2%86%92%20Reconnect%20(ping-before-join)%3Cbr%2F%3E%E2%86%92%20Anti-VPN%20offline%20blocklist%20%E2%86%92%20Country%22%5D%0A%20%20%20%20%20%20%20%20B4%20--%3E%20B5%5B%22DNS%20check%20(attack%20mode)%3Cbr%2F%3Ebare-IP%20handshake%20host%20%3D%20strike%22%5D%0A%20%20%20%20%20%20%20%20B5%20--%3E%20B6%7B%22Cached%20online%20anti-VPN%20verdict%3F%22%7D%0A%20%20%20%20%20%20%20%20B6%20--%3E%7C%22positive%22%7C%20X3%5B%22deny%20%2B%20firewall%22%5D%0A%20%20%20%20%20%20%20%20B6%20--%3E%7C%22clean%20%2F%20miss%22%7C%20B7%5B%22handshake%20accepted%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20LOGIN%5B%22Login%20(username%20now%20known)%22%5D%0A%20%20%20%20%20%20%20%20C1%5B%22Log4Shell%20filter%20on%20the%20username%22%5D%20--%3E%20C2%5B%22Accounts%20per%20IP%20%E2%86%92%20Nickname%20blacklist%3Cbr%2F%3E%E2%86%92%20Name-pattern%20%E2%86%92%20Strange-name%3Cbr%2F%3E(last%20two%3A%20attack%20mode%20only)%22%5D%0A%20%20%20%20%20%20%20%20C2%20--%3E%20C3%5B%22Async%20online%20anti-VPN%20chain%3Cbr%2F%3Egetipintel%20%E2%86%92%20proxycheck%20%E2%86%92%20iphub%22%5D%0A%20%20%20%20%20%20%20%20C3%20--%3E%7C%22VPN%22%7C%20X4%5B%22deny%20%2B%20firewall%22%5D%0A%20%20%20%20%20%20%20%20C3%20--%3E%7C%22clean%22%7C%20C4%5B%22Mojang%20authentication%20starts%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20POST%5B%22Post-login%22%5D%0A%20%20%20%20%20%20%20%20D1%5B%22Mark%20address%20verified%3Cbr%2F%3E(persistent%20whitelist%2C%20fresh%20start)%22%5D%20--%3E%20D2%5B%22Async%20anti-VPN%20recheck%3Cbr%2F%3Epositive%20%E2%86%92%20firewall%20%2B%20disconnect%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20PLAY%5B%22Play%20(for%20the%20rest%20of%20the%20session)%22%5D%0A%20%20%20%20%20%20%20%20E1%5B%22Packet%20flood%20VL%20scoring%3Cbr%2F%3E(every%20framed%20packet)%22%5D%0A%20%20%20%20%20%20%20%20E2%5B%22Chat%20%2F%20commands%3A%3Cbr%2F%3Efastchat%20%2B%20Log4Shell%20%2B%20password%20observer%22%5D%0A%20%20%20%20%20%20%20%20E3%5B%22Tab-complete%20expression%20filter%3Cbr%2F%3E(attack%20mode%20only)%22%5D%0A%20%20%20%20%20%20%20%20E4%5B%22Log4Shell%20filter%20on%20client-settings%20locale%22%5D%0A%20%20%20%20%20%20%20%20E5%5B%22Proxy-RTT%20middlebox%20monitor%3Cbr%2F%3E(KeepAlive%20ping%20vs%20kernel%20TCP%20RTT)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20PASS%20--%3E%20HANDSHAKE%20--%3E%20LOGIN%20--%3E%20POST%20--%3E%20PLAY%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=r('<p>The status (server list ping) path has its own short gate: every ping is recorded and rate-limited (<code>PingGuard</code>), and during attack mode a fresh cached MOTD is served directly — without firing <code>ProxyPingEvent</code> and without touching any backend server. See <a href="/pingless-studios-docs/nitrocord/architecture/attack-mode#server-list-pings-during-attacks">Attack Mode</a>.</p><div class="info custom-block"><p class="custom-block-title">Bedrock players</p><p>When Geyser compatibility is active (<code>compat.geyser</code> in <code>nitrocord.toml</code> and Floodgate or Geyser installed), usernames with the Floodgate prefix skip the username-stage checks, which would otherwise false-positive on Bedrock players.</p></div><hr><h2 id="the-violation-system" tabindex="-1">The violation system <a class="header-anchor" href="#the-violation-system" aria-label="Permalink to &quot;The violation system&quot;">​</a></h2><p>All checks feed one graduated escalation ladder. Every address carries a per-reason strike counter; repeated offences of the same kind escalate from a plain kick to a firewall ban.</p>',5)),(o(),n(d,null,{default:t(()=>[s(i,{id:"mermaid-137",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20T%5B%22A%20check%20triggers%22%5D%20--%3E%20S%5B%22Violations.strike%3Cbr%2F%3EAddressData.addViolation(reason)%22%5D%0A%20%20%20%20S%20--%3E%20D%7B%22Previous%20strike%20of%20the%20same%20reason%3Cbr%2F%3Eolder%20than%20violations.decay-ms%3F%3Cbr%2F%3E(default%20300%2C000%20ms)%22%7D%0A%20%20%20%20D%20--%3E%7C%22yes%22%7C%20R%5B%22counter%20restarts%20at%201%22%5D%0A%20%20%20%20D%20--%3E%7C%22no%22%7C%20I%5B%22counter%20%2B1%22%5D%0A%20%20%20%20R%20--%3E%20C%7B%22count%20%E2%89%A5%20violations.to-blacklist%3F%3Cbr%2F%3E(default%203)%22%7D%0A%20%20%20%20I%20--%3E%20C%0A%20%20%20%20C%20--%3E%7C%22no%22%7C%20DENY%5B%22deny%3A%20kick%20with%20the%20configured%20message%22%5D%0A%20%20%20%20C%20--%3E%7C%22yes%22%7C%20FW%5B%22firewall%20verdict%22%5D%0A%20%20%20%20FW%20--%3E%20V%5B%22Verdicts.apply%22%5D%20--%3E%20FM%5B%22FirewallManager.firewall%3Cbr%2F%3Eban%20for%20firewall.ban-time-seconds%20(default%2060s)%22%5D%0A%20%20%20%20DENY%20--%3E%20EV%5B%22NitroVerdictEvent%20fired%22%5D%0A%20%20%20%20FM%20--%3E%20EV%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[a(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=r('<p>Properties of the ladder:</p><ul><li><strong>19 violation reasons</strong>, one per detection: rate limit, reconnect, anti-VPN, country, accounts, nickname, fastchat, password, packets, TCP fingerprint, proxy-RTT, name-pattern, strange-name, timeout-flood, DNS check, Log4Shell, tab-exploit, improbable buffer and a catch-all.</li><li><strong>Strikes decay independently per reason.</strong> One strike of a kind expires after <code>violations.decay-ms</code> without a repeat, so a one-off mistake never accumulates into a ban.</li><li><strong>Every verdict flows through one funnel.</strong> <code>Verdicts.apply</code> records the block in the global statistics, logs it (throttled to one line per <code>performance.log-throttle-ms</code>, default 100 ms), mirrors firewall verdicts into the firewall manager and fires a <code>NitroVerdictEvent</code> — identical behaviour no matter which stage rejected the connection.</li><li><strong>A completed login wipes the slate.</strong> When an address finishes a full login, the whitelist service lifts any active ban and drops its entire violation state — verified players get a fresh start.</li></ul><p>Per-IP state lives in a Caffeine cache that expires ten minutes after the last access, so even a spoofed-source flood cannot grow memory unboundedly.</p><hr><h2 id="the-kernel-firewall" tabindex="-1">The kernel firewall <a class="header-anchor" href="#the-kernel-firewall" aria-label="Permalink to &quot;The kernel firewall&quot;">​</a></h2><p>The firewall is two layers with a strict authority order:</p>',6)),(o(),n(d,null,{default:t(()=>[s(i,{id:"mermaid-173",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20FW%5B%22FirewallManager.firewall(ip%2C%20reason)%3Cbr%2F%3Ecalled%20from%20any%20event%20loop%20%E2%80%94%20never%20blocks%22%5D%20--%3E%20AD%5B%22In-memory%20authority%3Cbr%2F%3Eper-IP%20ban%20expiry%20%2B%20reason%22%5D%0A%20%20%20%20FW%20--%3E%20Q%5B%22Bounded%20queue%3Cbr%2F%3Emax%2010%2C000%20pending%20kernel%20ops%22%5D%0A%20%20%20%20Q%20--%3E%20DT%5B%22nitrocord-firewall-kernel%20thread%3Cbr%2F%3Edrains%20every%20500%20ms%2C%20up%20to%20256%20ops%20per%20tick%22%5D%0A%20%20%20%20DT%20--%3E%20B%7B%22Adds%2Fremoves%20in%20batch%22%7D%0A%20%20%20%20B%20--%3E%7C%22fewer%20than%208%22%7C%20P1%5B%22one%20ipset%20add%2Fdel%20per%20entry%22%5D%0A%20%20%20%20B%20--%3E%7C%228%20or%20more%22%7C%20P2%5B%22single%20ipset%20restore%20-!%20-f%3Cbr%2F%3Efrom%20a%20temp%20file%22%5D%0A%20%20%20%20DT%20--%3E%20R%7B%22Bulk%20import%20queued%3F%22%7D%0A%20%20%20%20R%20--%3E%7C%22yes%22%7C%20TMP%5B%22restore%20into%20nitrocord-firewall-tmp%22%5D%20--%3E%20SWAP%5B%22ipset%20swap%3Cbr%2F%3Eatomic%20replacement%22%5D%20--%3E%20DES%5B%22destroy%20temp%20set%22%5D%0A%20%20%20%20P1%20--%3E%20SET%5B%22nitrocord-firewall%20ipset%3Cbr%2F%3Ehash%3Aip%2C%20entry%20timeout%20%3D%20ban%20time%22%5D%0A%20%20%20%20P2%20--%3E%20SET%0A%20%20%20%20SWAP%20--%3E%20SET%0A%20%20%20%20SET%20--%3E%20IPT%5B%22iptables%20INPUT%20--match-set%20nitrocord-firewall%20src%20-j%20DROP%22%5D%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[a(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=r(`<ul><li><strong>In-memory is authoritative.</strong> A ban is stamped into the address&#39;s state first and every <code>isFirewalled</code> lookup answers from memory, so protection works identically on any platform. The kernel layer is a mirror that makes floods cheaper, never the source of truth.</li><li><strong>Batched and atomic.</strong> Small batches run one <code>ipset</code> call per entry; batches of 8+ are applied with a single <code>ipset restore</code>. Bulk imports are built in a temporary set and swapped in atomically, so the iptables DROP rule always matches a fully populated set.</li><li><strong>Fail-safe by construction.</strong> All external commands run through explicit argument arrays (never a shell) on one daemon thread. Five consecutive command failures trip a circuit breaker that disables the kernel integration — the in-memory firewall keeps protecting. Queue overflow drops only the kernel mirror; the ban still applies. Kernel entries expire on their own via the set timeout even if the proxy dies.</li><li><strong>IPv4 at kernel level, IPv6 in memory.</strong> The ipset is IPv4-only; IPv6 bans are kept in memory and enforced at the accept-time gate.</li></ul><div class="tip custom-block"><p class="custom-block-title">Root optional, not required</p><p><code>firewall.ipset</code> needs root plus <code>ipset</code>/<code>iptables</code> on Linux. Without them NitroCord logs one clear warning and runs in-memory-only — every feature still works, floods just cost a little more CPU to drop.</p></div><hr><h2 id="component-map" tabindex="-1">Component map <a class="header-anchor" href="#component-map" aria-label="Permalink to &quot;Component map&quot;">​</a></h2><p>All NitroCord code lives under <code>com.nitrocord.*</code>:</p><table tabindex="0"><thead><tr><th>Package</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>com.nitrocord</code></td><td>Bootstrap singleton — owns both TOML configs, the brand, the message helper, Geyser detection</td></tr><tr><td><code>com.nitrocord.config</code></td><td>Typed views of <code>nitrocord.toml</code> and <code>protection.toml</code>; writes commented defaults on first run, merges new keys on upgrade</td></tr><tr><td><code>com.nitrocord.license</code></td><td>Altis license client — the single source of truth for whether protection may run</td></tr><tr><td><code>com.nitrocord.command</code></td><td><code>/nitrocord</code> (alias <code>/nc</code>) — stats, reload, firewall add/remove</td></tr><tr><td><code>com.nitrocord.api</code></td><td>Public plugin API: <code>NitroVerdictEvent</code>, <code>NitroFirewallEvent</code>, <code>NitroAttackModeEvent</code>, <code>Verdict</code></td></tr><tr><td><code>com.nitrocord.protection</code></td><td>Stage gates (<code>LoginGuard</code>, <code>PingGuard</code>) and shared verdict application (<code>Verdicts</code>)</td></tr><tr><td><code>com.nitrocord.protection.core</code></td><td>Attack-mode state machine, per-IP state, violation ladder, global stats, event posting, close helpers</td></tr><tr><td><code>com.nitrocord.protection.netty</code></td><td>The two pipeline handlers — firewall gate and packet guard</td></tr><tr><td><code>com.nitrocord.protection.checks</code></td><td>The eight registered anti-bot checks (rate limit, reconnect, anti-VPN, country, accounts, nickname, fastchat, password)</td></tr><tr><td><code>com.nitrocord.protection.names</code></td><td>Attack-mode username heuristics — name-pattern (Levenshtein similarity) and strange-name</td></tr><tr><td><code>com.nitrocord.protection.exploits</code></td><td>Log4Shell JNDI filter and tab-complete expression filter</td></tr><tr><td><code>com.nitrocord.protection.firewall</code></td><td>In-memory bans plus the ipset/iptables kernel mirror</td></tr><tr><td><code>com.nitrocord.protection.geoip</code></td><td>GeoLite2 country blocking — database download, auto-update, lookups</td></tr><tr><td><code>com.nitrocord.protection.antivpn</code></td><td>Offline blocklists plus the online provider chain, verdict caching and persistence</td></tr><tr><td><code>com.nitrocord.protection.fingerprint</code></td><td>Kernel <code>tcp_info</code> fingerprinting and proxy-RTT middlebox detection</td></tr><tr><td><code>com.nitrocord.protection.packets</code></td><td>Packet flood violation-level scoring</td></tr><tr><td><code>com.nitrocord.protection.motd</code></td><td>Null-ping-proof cached MOTD, custom MOTD rotation, fake player counts</td></tr><tr><td><code>com.nitrocord.protection.whitelist</code></td><td>Persistent verified-IP whitelist</td></tr><tr><td><code>com.nitrocord.protection.misc</code></td><td>DNS check, anti-hang read timeouts, timeout-flood tracking</td></tr><tr><td><code>com.nitrocord.perf</code></td><td>DynDNS backend re-resolution</td></tr></tbody></table><hr><h2 id="threading-model" tabindex="-1">Threading model <a class="header-anchor" href="#threading-model" aria-label="Permalink to &quot;Threading model&quot;">​</a></h2><p>One rule governs everything: <strong>Netty event loops never block.</strong> Every gate that runs on an event loop — firewall lookup, fingerprint, rate limit, name checks, MOTD serving — is pure in-memory work. Anything that needs the network or a subprocess runs on a background daemon thread or an async HTTP client.</p><table tabindex="0"><thead><tr><th>Thread</th><th>Cadence</th><th>Work</th></tr></thead><tbody><tr><td>Netty event loops</td><td>per I/O event</td><td>All gates, packet scoring, fingerprinting, MOTD serving — allocation-lean, never blocking</td></tr><tr><td><code>nitrocord-attack-mode</code></td><td>every 1 s</td><td>Attack-mode evaluation tick (transitions are also detected lazily on every query)</td></tr><tr><td><code>nitrocord-firewall-kernel</code></td><td>every 500 ms</td><td>Drains queued ipset/iptables operations</td></tr><tr><td><code>nitrocord-geoip</code></td><td>every <code>country.update-interval-hours</code> (24 h)</td><td>GeoLite2 database download and refresh</td></tr><tr><td><code>nitrocord-antivpn-refresh</code></td><td>every <code>antivpn.list-refresh-hours</code> (12 h) + every 10 min</td><td>Blocklist re-downloads; persisted verdict cache flush</td></tr><tr><td><code>nitrocord-whitelist</code></td><td>purge every 12 h, save every 60 min</td><td>Whitelist expiry and disk flush</td></tr><tr><td><code>nitrocord-license-check</code></td><td>every 6 h</td><td>License revalidation against the Altis platform</td></tr><tr><td>JDK HttpClient workers</td><td>on demand</td><td>Online anti-VPN provider queries — awaited asynchronously before Mojang auth, never on an event loop</td></tr></tbody></table><hr><h2 id="file-layout" tabindex="-1">File layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to &quot;File layout&quot;">​</a></h2><p>Everything NitroCord reads or writes lives in the proxy run directory:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;proxy run directory&gt;/</span></span>
<span class="line"><span>├── velocity.toml              # stock Velocity config (untouched semantics)</span></span>
<span class="line"><span>├── nitrocord.toml             # branding, theme colors, all messages, license key</span></span>
<span class="line"><span>├── protection.toml            # every protection knob</span></span>
<span class="line"><span>└── nitrocord/                 # NitroCord data directory</span></span>
<span class="line"><span>    ├── whitelist.txt          # persistent verified-IP whitelist</span></span>
<span class="line"><span>    ├── antivpn-cache.txt      # persisted anti-VPN verdicts</span></span>
<span class="line"><span>    ├── license.cache          # signed offline license grace cache</span></span>
<span class="line"><span>    └── GeoLite2-Country.mmdb  # GeoIP database (downloaded with your MaxMind key)</span></span></code></pre></div><p>All state files are written the same safe way: serialized to a temporary file first, then atomically moved over the target — a crash mid-save can never corrupt them. The license cache is what keeps protection running through a temporary outage of the license platform.</p><hr><h2 id="performance-notes" tabindex="-1">Performance notes <a class="header-anchor" href="#performance-notes" aria-label="Permalink to &quot;Performance notes&quot;">​</a></h2><p>NitroCord is built for the worst minute your proxy will ever have:</p><ul><li><strong>Zero-allocation hot paths.</strong> Violation counters pack timestamp and count into a single <code>AtomicLong</code> (one compare-and-set per strike), and the strike map is created lazily — an address that never misbehaves costs nothing. The packet scorer performs no allocation beyond its cache lookup. Whitelist lookups allocate nothing.</li><li><strong>Cached MOTD without event dispatch.</strong> During attack mode, pings are answered from a synthesized snapshot without firing <code>ProxyPingEvent</code> and without contacting backends — the plugin event path itself is removed from the attack surface.</li><li><strong>RST closes.</strong> Denied connections are closed with <code>SO_LINGER 0</code>: the kernel sends a TCP RST instead of running the FIN handshake, freeing the connection immediately.</li><li><strong>Kick suppression.</strong> Above <code>antiddos.kick-suppression-connections-per-second</code> (default 150 conn/s) during attack mode, no disconnect packet is written at all — the connection simply dies.</li><li><strong>Throttled logging.</strong> At most one protection log line per <code>performance.log-throttle-ms</code> (default 100 ms), so a flood cannot turn the log into a second attack.</li><li><strong>Bounded memory everywhere.</strong> Per-IP state expires 10 minutes after last access, packet flood state after 60 seconds, and the kernel-op queue is capped at 10,000 entries.</li></ul><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/nitrocord/architecture/attack-mode">Attack Mode →</a> — the state machine that ties it all together under load.</li><li><a href="/pingless-studios-docs/nitrocord/configuration/reference">Configuration Reference →</a> — every <code>protection.toml</code> key mentioned on this page.</li><li><a href="/pingless-studios-docs/nitrocord/user-guide/api">Plugin API Events →</a> — observe verdicts, firewall changes and attack-mode transitions from your own plugins.</li></ul>`,22))])}const A=c(h,[["render",m]]);export{b as __pageData,A as default};
